CREATE COLUMN TABLE "TEST_AP"."OBGS" ("AbsId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "BaseId" INTEGER CS_INT, "InitRate" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "FinancYear" LONGDATE CS_LONGDATE NOT NULL , "IsMain" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "RoundSys" SMALLINT CS_INT DEFAULT 0, "UserSign" SMALLINT CS_INT, "OcrCode" NVARCHAR(8), "OcrCode2" NVARCHAR(8), "OcrCode3" NVARCHAR(8), "OcrCode4" NVARCHAR(8), "OcrCode5" NVARCHAR(8), "PrjCode" NVARCHAR(20), PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBGS_SECOND" ON "TEST_AP"."OBGS" ( "Name" ASC, "FinancYear" ASC );
CREATE INDEX "OBGS_INTER_KEY" ON "TEST_AP"."OBGS" ( "BaseId" ASC )